import './extended-style.css';
import {validateExtendedContent,ITEM_ART} from './extended-content.js';
import {newExtended,extendedView,actExtended,undoExtended,optionOrder,defenderLane,keeperLane,recipeFor,loadExtended,saveExtended} from './extended-engine.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TITLES={'novel-v1':'Letters from Riverlight','quiz-v1':'The Star Archive','sports-v1':'Riverlight Cup','merge-v1':'The Makers Guild'};
const ART={'novel-v1':'vn','quiz-v1':'quiz','sports-v1':'sports','merge-v1':'merge'};
const NAMES={engineer:'The engineer',archivist:'The archivist',captain:'The captain'};
const LANES=['Left wing','Centre','Right wing'];
const seed=()=>{try{return crypto.getRandomValues(new Uint32Array(1))[0]||1}catch{return Date.now()%4294967295||1}};
export function mountExtended(container,{pack:input,assets={},onExit=()=>{},onLibrary=()=>{},onProgress=()=>{},storage=localStorage}={}){
 const pack=validateExtendedContent(input),kind=pack.template.split('-')[0];
 const restored=loadExtended(storage,pack,seed());let record=restored.record,notice=restored.notice,v=extendedView(pack,record),modal=null,returnFocus=null,selected=null,combine=null,alive=true;
 const art=assets.extended||{};
 const url=value=>{const path=typeof value==='string'?value:value?.url;return typeof path==='string'&&/^\/game-modes\/extended-art\/[a-zA-Z0-9_./-]+\.(webp|png|jpg)$/.test(path)?path:''};
 const image=(value,alt='',cls='')=>url(value)?`<img src="${esc(url(value))}" alt="${esc(alt)}" class="${cls}" draggable="false">`:'';
 const button=(label,action,attrs='',cls='')=>`<button type="button" class="rx-button ${cls}" data-rx="${action}" ${attrs}>${label}</button>`;
 const sourceButton=(refs,label='Read the source')=>button(label,'source',`data-refs="${esc(refs.join(','))}"`,'rx-source');
 const sourceHTML=refs=>refs.map(id=>{const s=pack.sources.find(s=>s.id===id);return s?`<blockquote><p>${esc(s.excerpt)}</p><footer>${esc(s.title)}<br>${esc(s.locator)}</footer></blockquote>`:''}).join('');
 const icon=(index,cls='')=>image(art.icons?.[ITEM_ART[index]],'',`rx-item-icon ${cls}`);
 const sceneImage=()=>image(art.backgrounds?.[ART[pack.template]],'','rx-backdrop');
 const heading=text=>`<h2 tabindex="-1" data-rx-heading>${esc(text)}</h2>`;
 const firstAttempts=()=>v.attempts?.filter((a,i)=>a.length&&a[0]===pack.questions[i].solution).length||0;
 function question(){const q=pack.questions[v.index],attempts=v.attempts[v.index],settled=attempts.includes(q.solution),last=attempts.at(-1);return `<section class="rx-question"><p class="rx-progress">${kind==='sports'?'Possession':'Star'} ${v.index+1} of ${pack.questions.length}</p>${heading(q.prompt)}<div class="rx-answers" role="group" aria-label="Answer choices">${optionOrder(pack,record,v.index).map((a,i)=>button(`<span class="rx-letter">${String.fromCharCode(65+i)}</span><span>${esc(q.options[a].label)}</span>`,'answer',`data-answer="${a}" ${settled||attempts.includes(a)?'disabled':''}`,(attempts.includes(a)?a===q.solution?'rx-correct':'rx-tried':'')+' rx-answer')).join('')}</div>${last!==undefined?`<div class="rx-feedback" tabindex="-1" data-rx-feedback role="status"><strong>${settled?'Connection made':'A clue to reconsider'}</strong><p>${esc(q.options[last].feedback)}</p>${settled?`<p>${esc(q.explanation)}</p>`:''}</div>`:''}<div class="rx-actions">${sourceButton(q.sourceRefs)}${settled?button(kind==='sports'?'Take the field':v.index===7?'Complete the constellation':'Next star','next','','rx-primary'):''}</div><p class="rx-note">No timer. Try each idea, read its feedback and use the evidence.</p></section>`}
 function novel(){const n=pack.nodes[v.node],pending=v.pending;return `<section class="rx-novel-stage">${sceneImage()}<div class="rx-portraits">${image(art.portraits?.[n.speaker],NAMES[n.speaker],'rx-speaking')}${image(art.portraits?.[n.speaker==='archivist'?'engineer':'archivist'],'','rx-listening')}</div><div class="rx-dialogue"><div class="rx-dialogue-top"><span>${NAMES[n.speaker]}</span>${button('Story journal','journal')}</div>${heading(pending===null?n.title:'Your decision changes the conversation')}<p>${esc(pending===null?n.text:n.choices[pending].consequence)}</p>${sourceButton(pending===null?n.sourceRefs:n.choices[pending].sourceRefs)}${pending===null?`<div class="rx-story-choices">${n.choices.map((c,i)=>button(esc(c.label),'choose',`data-choice="${i}"`)).join('')}</div>`:`<div class="rx-actions">${button('Continue the story','continue','','rx-primary')}</div>`}</div></section>`}
 function quiz(){const points=[[100,360],[220,290],[160,180],[310,130],[425,220],[360,340],[525,355],[565,150]];return `<div class="rx-quiz-layout"><section class="rx-observatory" aria-label="Constellation progress">${sceneImage()}<svg viewBox="0 0 660 480" role="img" aria-label="${v.index} of eight stars connected"><path class="rx-star-route" d="${points.map(([x,y],i)=>`${i?'L':'M'}${x} ${y}`).join(' ')}"/>${points.map(([x,y],i)=>`<g class="rx-star ${i<v.index?'is-lit':''} ${i===v.index?'is-current':''}" transform="translate(${x} ${y})"><circle r="${i===v.index?13:9}"/><text x="0" y="35" text-anchor="middle">${i+1}</text></g>`).join('')}</svg><div class="rx-observatory-caption"><h2>Ideas become a constellation.</h2><p>Eight connections. Time to think.</p></div></section>${question()}</div>`}
 const ballPosition=(zone,lane)=>({x:150+zone*165,y:120+lane*105});
 function pitch(){const pos=ballPosition(v.zone,v.lane),def=ballPosition(Math.min(3,v.zone+1),defenderLane(v)),keeper=ballPosition(3,keeperLane(v));return `<div class="rx-pitch" aria-label="Football pitch"><div class="rx-field">${sceneImage()}<svg viewBox="0 0 820 460" role="img" aria-label="Ball in zone ${v.zone}, ${LANES[v.lane]}. Defender blocks ${LANES[defenderLane(v)]}; keeper covers ${LANES[keeperLane(v)]}."><path d="M315 84V358M480 84V358M645 84V358" class="rx-zone-line"/>${[0,1,2].map(l=>{const p=ballPosition(Math.min(3,v.zone+1),l);return `<g class="rx-player" transform="translate(${p.x} ${p.y})"><circle r="19"/><text text-anchor="middle" y="6">${l+7}</text></g>`}).join('')}<g class="rx-defender" transform="translate(${def.x+47} ${def.y})"><circle r="20"/><text text-anchor="middle" y="6">×</text></g><g class="rx-keeper" transform="translate(705 ${keeper.y})"><circle r="17"/><text text-anchor="middle" y="5">K</text></g><g class="rx-ball" transform="translate(${pos.x} ${pos.y})"><circle r="12"/><path d="M-5-4L4-5L7 3L0 7L-6 2Z"/></g><text x="410" y="430" text-anchor="middle" class="rx-pitch-label">Attack toward the right-hand goal</text></svg></div><div class="rx-score"><span>${esc(pack.teamName)}</span><strong>${v.score} <small>–</small> ${v.opponent}</strong><span>${esc(pack.opponentName)}</span></div></div>`}
 function tactics(){const canShoot=v.zone>=1&&v.energy>=1;return `<section class="rx-tactics"><p class="rx-progress">Possession ${v.index+1} of 6</p>${heading(v.phase==='result'?v.results.at(-1).message:'Find a way through.')}<div class="rx-match-stats"><div><span>Stamina</span><strong>${v.energy} / 5</strong></div><div><span>Zone</span><strong>${v.zone} / 3</strong></div><div><span>Insight</span><strong>+${v.insight}</strong></div></div>${v.phase==='result'?`<p>${v.results.at(-1).conceded?'The opposition countered before your attack reached zone 3. They score once.':'Your team kept the opposition out on this possession.'}</p>${button(v.index===5?'Read the match report':'Next possession','next-possession','','rx-primary')}`:`<p>Defender blocks <b>${LANES[defenderLane(v)].toLowerCase()}</b>. Keeper covers <b>${LANES[keeperLane(v)].toLowerCase()}</b>.</p><div class="rx-tactical-moves">${LANES.map((lane,i)=>button(`${i===1?'Drive centre':`Pass ${i===0?'left':'right'}`}<small>${i===1?'2 stamina · advance 2':'1 stamina · advance 1'}</small>`,'move',`data-lane="${i}" ${v.energy<(i===1?2:1)?'disabled':''}`)).join('')}</div><p class="rx-note">Blocked moves spend stamina without advancing. An open shot needs power 3; shooting at the keeper needs 4. Power = zone + insight. Keep 1 stamina to shoot.</p><div class="rx-shots">${LANES.map((lane,i)=>button(`Shoot ${i===1?'centre':i===0?'left':'right'}`,'shoot',`data-lane="${i}" ${canShoot?'':'disabled'}`,'rx-primary')).join('')}</div>${v.last?.type==='move'?`<p class="rx-feedback" role="status">${v.last.blocked?'Blocked. The defender shifts; look for the open lane.':'Pass complete. Your attack moves up the pitch.'}</p>`:''}`}<p class="rx-note">Fictional match rules. The opposition can counter on possessions 2 and 5 if your attack stops before zone 3.</p></section>`}
 function sports(){return `<div class="rx-sports-layout">${pitch()}${['question','feedback'].includes(v.phase)?question():tactics()}</div>`}
 function recipeHTML(index){const r=pack.recipes[index];return `<div class="rx-recipe"><div class="rx-recipe-symbols">${icon(r.inputs[0])}<span>+</span>${icon(r.inputs[1])}<span>=</span>${icon(index+2)}</div><h3>${esc(pack.items[r.inputs[0]].name)} + ${esc(pack.items[r.inputs[1]].name)} = ${esc(pack.items[index+2].name)}</h3><p>${esc(r.explanation)}</p>${sourceButton(r.sourceRefs)}</div>`}
 function merge(){const current=selected!==null?v.board[selected]:null,r=combine?recipeFor(pack,v.board[combine.from],v.board[combine.to]):-1;return `<div class="rx-workshop-layout"><section class="rx-workbench">${sceneImage()}<div class="rx-workbench-body"><div class="rx-collect">${[0,1].map(i=>button(`${icon(i)}<span>Collect ${esc(pack.items[i].name)}</span>`,'collect',`data-item="${i}" ${!v.board.includes(null)?'disabled':''}`)).join('')}</div><div class="rx-grid" role="group" aria-label="Crafting board">${v.board.map((item,i)=>button(`${item===null?'<span class="rx-empty-slot">+</span>':`${icon(item)}<span class="rx-piece-name">${esc(pack.items[item].name)}</span>`}`,'slot',`data-slot="${i}" aria-label="Slot ${i+1}: ${item===null?'empty':esc(pack.items[item].name)}" aria-pressed="${selected===i}"`,'rx-slot '+(selected===i?'is-selected':''))).join('')}</div><div class="rx-board-tools">${button('Recipe journal','recipes')}${button('Undo move','undo',record.history.length?'':'disabled')}${button('Recycle selected','recycle',current===null?'disabled':'')}</div><p class="rx-note">Select a piece, then an empty slot to move it or another piece to combine. Base resources are unlimited. Undo restores consumed pieces and deliveries.</p></div></section><aside class="rx-orders">${heading('Commissions for the town')}<p class="rx-note">Symbols represent ideas. A combination records a conceptual connection; it is not a scientific transformation.</p>${pack.orders.map((o,i)=>{const available=v.board.filter(x=>x===o.item).length;return `<article class="rx-order ${v.delivered[i]?'is-delivered':''}">${icon(o.item)}<div><h3>${esc(o.title)}</h3><p>${esc(o.purpose)}</p><p><b>${esc(pack.items[o.item].name)}</b> ${v.delivered[i]?'Delivered':`${available} / ${o.quantity}`}</p><div class="rx-actions">${sourceButton(o.sourceRefs,'Evidence')}${button(v.delivered[i]?'Delivered':'Deliver','deliver',`data-order="${i}" ${v.delivered[i]||available<o.quantity?'disabled':''}`,'rx-primary')}</div></div></article>`}).join('')}${current!==null?`<section class="rx-selected"><h3>${esc(pack.items[current].name)}</h3><p>${esc(pack.items[current].description)}</p>${sourceButton(pack.items[current].sourceRefs)}</section>`:v.last?.type==='combine'?`<section class="rx-craft-preview" role="status"><strong>Connection crafted</strong>${recipeHTML(v.last.recipe)}</section>`:''}</aside></div>`}
 function complete(){const ending=kind==='novel'?pack.endings[v.node-6]:null;return `<section class="rx-ending">${sceneImage()}<div class="rx-ending-paper"><p class="rx-progress">${kind==='novel'?'A letter for tomorrow':kind==='sports'?'The match report':kind==='merge'?'The guild commissions are complete':'The constellation is complete'}</p>${heading(ending?.title||pack.title)}${ending?`<p>${esc(ending.text)}</p>${sourceButton(ending.sourceRefs)}`:kind==='sports'?`<div class="rx-final-score">${v.score} – ${v.opponent}</div><p>${v.score>v.opponent?'Your team wins.':v.score===v.opponent?'The match is drawn.':'The opposition wins this time.'} You completed all six possessions.</p>`:kind==='merge'?`<p>All three orders delivered. You explored ${v.discovered.length} of six recipe connections.</p>`:'<p>All eight questions explored.</p>'}${['quiz','sports'].includes(kind)?`<p>${firstAttempts()} of ${pack.questions.length} correct on the first attempt; ${pack.questions.length-firstAttempts()} revisited with feedback. This is a record of this run, not a measure of mastery.</p><details class="rx-recap"><summary>Review your learning record</summary>${pack.questions.map((q,i)=>`<article><h3>${esc(q.prompt)}</h3><p>${esc(q.options[q.solution].label)}</p><p>${esc(q.explanation)}</p><p>${v.attempts[i].length===1?'First attempt':'Revisited with feedback'}</p>${sourceButton(q.sourceRefs)}</article>`).join('')}</details>`:''}<h3>${esc(pack.debrief.question)}</h3><p>${esc(pack.debrief.explanation)}</p>${sourceButton(pack.debrief.sourceRefs)}<div class="rx-actions">${kind==='novel'?button('Read your story journal','journal'):''}${kind==='merge'?button('Undo last delivery','undo'):''}${button('Play again','restart','','rx-primary')}${button('Choose another game','exit')}</div></div></section>`}
 const HELP={novel:'Read the scene and sources, make a choice, then continue. Your route changes the conversations and ending. The journal records only decisions you actually made. Replay to explore a different route.',quiz:'Connect eight stars by answering eight questions. Answers shuffle once per run. Every incorrect option has feedback, and you can retry without a timer. The ending separates first attempts from corrected answers.',sports:'Answer a question before each of six possessions. A correct first attempt adds one insight to shot power; corrected answers still let you play. Choose an open lane: wings cost one stamina and advance one zone; centre costs two and advances two. The defender moves after each action. Shoot with at least one stamina: power is zone plus insight, requiring three for an open lane or four at the keeper. Reaching zone three prevents a counter. Opponents can counter in possessions two and five. All match values are fictional.',merge:'Collect either unlimited base resource. Select a board piece and click an empty slot to move it, or a second piece to preview a recipe. Read the explanation and combine. Check the recipe journal for every recipe. Deliver the three commissions. Recycle any piece to free space; Undo restores the last action, including a delivery. These symbolic recipes represent conceptual relationships.'};
 function modalHTML(){if(!modal)return '';let body='';if(modal.kind==='source')body=`<h2 id="rx-dialog-title">Supporting passages</h2>${sourceHTML(modal.refs)}`;else if(modal.kind==='craft')body=`<h2 id="rx-dialog-title">A new connection</h2>${recipeHTML(recipeFor(pack,v.board[combine.from],v.board[combine.to]))}${button('Combine these pieces','combine','','rx-primary')}`;else if(modal.kind==='recipes')body=`<h2 id="rx-dialog-title">The recipe journal</h2><p>All recipes are available from the start. Every result can be made from the two base resources.</p>${pack.recipes.map((_,i)=>recipeHTML(i)).join('')}`;else if(modal.kind==='journal')body=`<h2 id="rx-dialog-title">Your story journal</h2>${v.journal.length?v.journal.map(j=>{const n=pack.nodes[j.node],c=n.choices[j.choice];return `<article><h3>${esc(n.title)}</h3><p><b>${esc(c.label)}</b></p><p>${esc(c.consequence)}</p>${sourceHTML(c.sourceRefs)}</article>`}).join(''):'<p>Your first decision will appear here.</p>'}`;else if(modal.kind==='restart')body=`<h2 id="rx-dialog-title">Begin a new run?</h2><p>This replaces this subject’s current run on this device.</p>${button('Begin new run','restart-confirm','','rx-primary')}`;else body=`<h2 id="rx-dialog-title">How to play ${esc(TITLES[pack.template])}</h2><p>${HELP[kind]}</p>`;return `<div class="rx-modal-shade"><section class="rx-modal" role="dialog" aria-modal="true" aria-labelledby="rx-dialog-title">${button('Close','close','','rx-modal-close')}${body}</section></div>`}
 function render(focus='heading',previous=null){if(!alive)return;v=extendedView(pack,record);container.dataset.phase=v.phase;container.dataset.completed=String(v.phase==='complete');container.dataset.format=pack.template;container.innerHTML=`<div class="rx-game rx-${kind}"><header class="rx-header"><div><h1>${TITLES[pack.template]}</h1><p>${esc(pack.title)}</p></div><nav aria-label="Game navigation">${button('How to play','help')}${button('Resource library','library')}${button('Restart','restart')}${button('Game library','exit')}</nav></header><details class="rx-brief"><summary>${esc(pack.subtitle)}</summary><p>${esc(pack.hook)}</p></details>${v.phase==='complete'?complete():kind==='novel'?novel():kind==='quiz'?quiz():kind==='sports'?sports():merge()}<footer class="rx-save" role="status">${esc(notice||'Progress is saved on this device.')}</footer>${modalHTML()}</div>`;
  if(modal)container.querySelector('.rx-modal-close')?.focus();else if(focus==='heading')container.querySelector('[data-rx-heading]')?.focus({preventScroll:true});else if(focus==='feedback')container.querySelector('[data-rx-feedback]')?.focus({preventScroll:true});else if(focus){const target=container.querySelector(focus);(target&&!target.disabled?target:container.querySelector('[data-rx-heading]'))?.focus({preventScroll:true});}
  if(kind==='sports'&&previous&&v.last&&['play','result'].includes(v.phase)&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const from=ballPosition(previous.zone,previous.lane),to=ballPosition(v.zone,v.lane);container.querySelector('.rx-ball')?.animate([{transform:`translate(${from.x}px,${from.y}px)`},{transform:`translate(${to.x}px,${to.y}px)`}],{duration:420,easing:'ease-out'})}
 }
 function commit(action,focus='heading'){const previous=v;record=actExtended(pack,record,action);notice=saveExtended(storage,pack,record);onProgress({pack,record,kind:'classic'});selected=null;combine=null;render(focus,previous)}
 function open(m,b){returnFocus=b?`[data-rx="${b.dataset.rx}"]${b.dataset.refs?`[data-refs="${CSS.escape(b.dataset.refs)}"]`:''}`:null;modal=m;render(null)}
 function close(){if(modal?.kind==='craft')combine=null;modal=null;render(returnFocus||'heading')}
 function click(event){const b=event.target.closest('[data-rx]');if(!b||!container.contains(b)||b.disabled)return;const a=b.dataset.rx;try{
  if(a==='exit'){onExit();return}if(a==='library'){onLibrary();return}
  if(['help','recipes','journal','restart'].includes(a)){open({kind:a},b);return}
  if(a==='source'){const refs=(b.dataset.refs||'').split(',').filter(id=>pack.sources.some(s=>s.id===id));if(['recipes','craft'].includes(modal?.kind)){modal={kind:'source',refs,back:modal.kind};render(null)}else open({kind:'source',refs},b);return}
  if(a==='close'){if(modal?.back){modal={kind:modal.back};render(null)}else close();return}
  if(a==='restart-confirm'){record=newExtended(pack,seed());notice=saveExtended(storage,pack,record);modal=null;selected=null;combine=null;render();return}
  if(a==='choose')commit({type:'choose',choice:Number(b.dataset.choice)});
  else if(['continue','next','next-possession'].includes(a))commit({type:a});
  else if(a==='answer')commit({type:a,answer:Number(b.dataset.answer)},'feedback');
  else if(['move','shoot'].includes(a))commit({type:a,lane:Number(b.dataset.lane)},a==='move'?'[data-rx="move"][data-lane="0"]':'heading');
  else if(a==='collect')commit({type:a,item:Number(b.dataset.item)},`[data-rx="collect"][data-item="${b.dataset.item}"]`);
  else if(a==='slot'){const slot=Number(b.dataset.slot);if(selected===null){if(v.board[slot]!==null)selected=slot;combine=null;render(`[data-slot="${slot}"]`)}else if(selected===slot){selected=null;combine=null;render(`[data-slot="${slot}"]`)}else if(v.board[slot]===null)commit({type:'move',from:selected,to:slot},`[data-slot="${slot}"]`);else{const r=recipeFor(pack,v.board[selected],v.board[slot]);if(r<0){notice='No recipe uses these two pieces. The new piece is selected; check the recipe journal.';selected=slot;combine=null;render(`[data-slot="${slot}"]`)}else{combine={from:selected,to:slot};open({kind:'craft'},b)}}}
  else if(a==='combine'&&combine){modal=null;commit({type:'combine',...combine},`[data-slot="${combine.to}"]`);}
  else if(a==='cancel-combine'){combine=null;selected=null;render('[data-slot="0"]')}
  else if(a==='recycle'&&selected!==null)commit({type:a,slot:selected},`[data-slot="${selected}"]`);
  else if(a==='deliver')commit({type:a,order:Number(b.dataset.order)});
  else if(a==='undo'){record=undoExtended(pack,record);notice=saveExtended(storage,pack,record)||'Last move undone.';selected=null;combine=null;render('[data-rx="undo"]')}
 }catch(e){notice=e.message;render('heading')}}
 function keydown(e){if(modal){if(e.key==='Escape'){e.preventDefault();close();return}if(e.key==='Tab'){const nodes=[...container.querySelectorAll('.rx-modal button:not(:disabled),.rx-modal a,.rx-modal summary')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||!container.querySelector('.rx-modal')?.contains(document.activeElement))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||!container.querySelector('.rx-modal')?.contains(document.activeElement))){e.preventDefault();first?.focus()}}return}
  const slot=e.target.closest('[data-slot]');if(slot&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const i=Number(slot.dataset.slot),next=Math.max(0,Math.min(15,i+({ArrowLeft:-1,ArrowRight:1,ArrowUp:-4,ArrowDown:4}[e.key])));container.querySelector(`[data-slot="${next}"]`)?.focus()}}
 container.addEventListener('click',click);container.addEventListener('keydown',keydown);render();return {destroy(){alive=false;container.removeEventListener('click',click);container.removeEventListener('keydown',keydown);container.innerHTML='';for(const k of['phase','completed','format'])delete container.dataset[k]}};
}
