import {learningJournal} from './game-modes/learning-client.js';
import {revisionEditorHTML,editRevisionField} from './revision-editor.js';
import {validatePlayableContent,GAME_TEMPLATES,gameReviewHTML} from './game-modes/content-registry.js';
// The browser presents documents and chapters; identity, source bindings and
// provider credentials remain on the server.
export class ResourceWorkshop {
 constructor(expansion,options={}){this.expansion=expansion;this.options=options;this.template=options.template||'underlight-v1';this.resources=[];this.jobs=[];this.health=null;this.selected=new Set();this.form={title:'',text:'',filename:'',goal:'',level:'New to this topic'};this.requestKey=null;this.running=new Set();this.timer=null;}
 get g(){return this.expansion.get()}
 async request(path,body){const response=await fetch('/api/workshop/'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json','X-Lanternbound-Workshop':'1'}:{},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await response.json()}catch{throw Error('The resource service is unavailable. Your existing adventures are still ready to play.')}if(!response.ok)throw Object.assign(Error(data.error||data.message||'The request did not finish.'),{status:response.status});return data}
 async refresh(){const health=await this.request('health');this.health=health;const data=await this.request('library');this.resources=data.resources;this.jobs=data.jobs;}
 async open(){const m={kind:'resource-library',busy:true};this.g.openModal(m);try{await this.refresh()}catch(e){m.feedback=e.message;m.signin=e.status===401}finally{m.busy=false;if(this.g.modal===m)this.g.renderModal()}}
 status(status){return {queued:'Waiting to start',starting:'Submitting to Muse Wonder',running:'Writing your chapter',review:'Ready for review',published:'Reviewed chapter',failed:'Needs attention',interrupted:'Connection interrupted'}[status]||status}
 panel(m,{esc,button,wrap}){
  if(!m.kind.startsWith('resource-'))return null;
  const status=`<p class="resource-status" role="status">${esc(m.feedback||'')}</p>`,back=button('Resource library','resource-open'),disabled=m.busy?'disabled':'';let html='';
  if(m.kind==='resource-revision')html=`<p class="town-kicker">Revise a copy</p><h2 id="modal-title">Refine the learning, keep the original</h2><p>Edit the story, questions, feedback or answers below. Source passages, citations and the game structure remain attached to the original reviewed material.</p>${revisionEditorHTML(m.edited,esc,m)}${status}<div class="row">${button('Review revised copy','resource-revision-review',disabled,'primary')}${button('Back to original','resource-revision-cancel',disabled)}</div>`;
  if(m.kind==='resource-revision-review')html=`<p class="town-kicker">Revised copy · not saved</p><h2 id="modal-title">${esc(m.edited.title)}</h2><p>${esc(m.edited.hook)}</p>${gameReviewHTML(m.edited,esc)}<p>The original chapter and its saved journeys stay available. Saving this copy uses one of the workshop’s ten daily draft slots, without another Muse Wonder request. Review the stored copy before publishing it.</p>${status}<div class="row">${button(m.busy?'Saving revised copy…':'Save revised copy','resource-revision-save',disabled,'primary')}${button('Keep editing','resource-revision-edit',disabled)}</div>`;
  if(m.kind==='resource-library')html=`<p class="town-kicker">Your resource library</p><h2 id="modal-title">Bring a subject into the story</h2><p>Add learning material, check its source passages, then turn a learning goal into a role-playing game, adventure, draft, town simulation, visual novel, quiz, sports match or crafting game. Each format reuses its own world and rules.</p>${m.signin?'<a class="workshop-signin" href="/account.html" target="_top">Sign in to your learner account</a>':`<div class="row">${button('Add learning material','resource-add',disabled,'primary')}${button('Plan a chapter','resource-plan',!this.resources.some(r=>r.status==='reviewed')||m.busy?'disabled':'')}${button('Refresh library','resource-refresh',disabled)}</div>${!m.busy&&!this.health?.configured?'<p class="workshop-notice">Muse Wonder generation is not connected yet. You can upload and review sources now; generation will become available when the connection is configured.</p>':''}<h3>Learning material</h3>${this.resources.length?this.resources.map(r=>`<article class="resource-row"><div><b>${esc(r.title)}</b><small>${r.units.length} source passages · ${r.status==='reviewed'?'Reviewed':'Needs review'}</small></div>${button('Read source','resource-source',`data-id="${r.id}"`)}</article>`).join(''):'<p class="muted">Your library is empty. Start with notes, a text file or a Markdown document.</p>'}<h3>Chapters</h3>${this.jobs.length?this.jobs.map(j=>`<article class="resource-row"><div><b>${esc(j.draft?.title||j.goal)}</b><small>${esc(this.status(j.status))}</small></div>${button('Open chapter','resource-job',`data-id="${j.id}"`)}</article>`).join(''):'<p class="muted">Generated chapters will appear here, including their review status.</p>'}`}<p class="muted">Uploads are saved in this private workspace library. Selected, reviewed passages are sent to Meta and stored with the background response when you request generation.</p>${status}${button('Return to the world','close')}`;
  if(m.kind==='resource-add')html=`<p class="town-kicker">Add learning material</p><h2 id="modal-title">A source for your next adventure</h2><p>Use material you have permission to upload. Text and Markdown are supported, up to 64 KB and 60,000 characters. PDF and Word extraction will come later.</p><label for="resource-file">Choose a text or Markdown file</label><input id="resource-file" type="file" accept=".txt,.md,.markdown,text/plain,text/markdown" ${disabled}><label for="resource-title">Source title</label><input id="resource-title" maxlength="160" value="${esc(this.form.title)}" ${disabled}><label for="resource-text">Or paste learning notes</label><textarea id="resource-text" rows="10" maxlength="60000" ${disabled}>${esc(this.form.text)}</textarea><p class="muted">Paragraph references are created from this text. Check the extracted passages before using them.</p>${status}<div class="row">${button(m.busy?'Saving source…':'Save and review source','resource-upload',disabled,'primary')}${back}</div>`;
  if(m.kind==='resource-source'){const r=m.resource;html=`<p class="town-kicker">Source review · ${r.status==='reviewed'?'reviewed':'not yet reviewed'}</p><h2 id="modal-title">${esc(r.title)}</h2><p>Check that the text is complete and suitable for the learning goal. These exact passages can be used as citations.</p><div class="source-passages">${r.units.map(u=>`<section><h3>${esc(u.locator)}</h3><p>${esc(u.excerpt)}</p></section>`).join('')}</div>${r.status!=='reviewed'?`<label class="workshop-check"><input id="resource-confirm" type="checkbox" ${m.confirmed?'checked':''}>I have checked these passages and can use this material.</label>${button('Mark source reviewed','resource-review',!m.confirmed||m.busy?'disabled':'','primary')}`:''}${status}${back}`}
  if(m.kind==='resource-plan')html=`<p class="town-kicker">Shape your learning game</p><h2 id="modal-title">What should the adventure teach?</h2><p>Choose a format that fits the source. Review the resulting story, learning actions and evidence before playing.</p><label for="resource-template">Game format</label><select id="resource-template">${GAME_TEMPLATES.filter(t=>!this.options.templates||this.options.templates.includes(t.id)).map(t=>`<option value="${t.id}" ${t.id===this.template?'selected':''}>${esc(t.name)}</option>`).join('')}</select><fieldset><legend>Choose up to three reviewed sources</legend>${this.resources.filter(r=>r.status==='reviewed').map(r=>`<label class="workshop-check"><input type="checkbox" data-resource="${r.id}" ${this.selected.has(r.id)?'checked':''}>${esc(r.title)}</label>`).join('')}</fieldset><label for="resource-goal">Learning goal</label><textarea id="resource-goal" rows="3" maxlength="1200" placeholder="What should the learner be able to explain or do?">${esc(this.form.goal)}</textarea><label for="resource-level">Learner’s level and needs</label><input id="resource-level" maxlength="240" value="${esc(this.form.level)}"><p class="muted">Muse Wonder uses a maximum of twelve relevant passages. You will review the generated facts, answers and source references before playing. Generation uses your connected Meta API account.</p>${!this.health?.configured?'<p class="workshop-notice">Waiting for the Muse Wonder connection. Sources can still be reviewed and reused.</p>':''}${status}<div class="row">${button(m.busy?'Preparing request…':'Generate chapter with Muse Wonder','resource-generate',!this.health?.configured||m.busy?'disabled':'','primary')}${back}</div>`;
  if(m.kind==='resource-job'){
   const j=m.job,c=j?.draft?validatePlayableContent(j.draft):null;html=`<p class="town-kicker">${esc(this.status(j.status))} · Muse Wonder</p><h2 id="modal-title">${esc(c?.title||'Your chapter request')}</h2><p>${esc(j.goal)}</p>${j.revisionOf?'<p class="workshop-notice">Revised copy. The original chapter remains in your library.</p>':''}${j.error?`<p class="workshop-notice">${esc(j.error)}</p>`:''}${['starting','running'].includes(j.status)?'<p role="status">Muse Wonder is writing and the server will check the result. You can leave this screen and reopen the request from your library. A reconnect does not create another generation request.</p>':''}${j.status==='queued'?button('Start this request','resource-run',disabled,'primary'):''}${c?`<p>${esc(c.hook)}</p>${c.template!=='underlight-v1'?gameReviewHTML(c,esc):Object.values(c.challenges).map(q=>`<section class="draft-mechanism"><h3>${esc(q.title)}</h3><p><b>Learning goal:</b> ${esc(q.objective)}</p><p>${esc(q.prompt)}</p><p><b>Expected answer:</b> ${esc(Array.isArray(q.solution)?q.solution.map(v=>q.options?.[v]||q.labels[v]).join(' → '):`${q.labels[0]}: ${q.solution}; ${q.labels[1]}: ${q.total-q.solution}`)}</p><p>${esc(q.explanation)}</p><details><summary>Check supporting sources</summary>${q.sourceRefs.map(id=>{const s=c.sources.find(s=>s.id===id);return `<blockquote>${esc(s.excerpt)}<footer>${esc(s.title)} · ${esc(s.locator)}</footer></blockquote>`}).join('')}</details></section>`).join('')}${c.template==='underlight-v1'?`<h3>Possible endings</h3><p>${esc(c.aftermath.gardens)}</p><p>${esc(c.aftermath.homes)}</p>`:''}${j.status==='review'?`<label class="workshop-check"><input id="draft-confirm" type="checkbox" ${m.confirmed?'checked':''}>I checked the teaching, solutions and supporting passages.</label>${button('Save reviewed chapter','resource-publish',!m.confirmed||m.busy?'disabled':'','primary')}${button('Download draft for editing','resource-download',disabled)}`:''}${j.status==='published'?(this.options.onActivate&&c.template==='underlight-v1'?'<p><a href="/">Open the RPG to use this chapter</a></p>':button('Use this chapter','resource-use',c.template==='underlight-v1'&&j.topicId!==this.g.pack.id?'disabled':'','primary'))+button('Download chapter','resource-download')+(!this.options.onActivate&&c.template==='underlight-v1'&&j.topicId!==this.g.pack.id?'<p>Switch back to the story used for this request before activating it.</p>':''):''}`:''}${c&&['review','published'].includes(j.status)?button('Revise a copy','resource-revise',disabled):''}${status}<div class="row">${button('Check request status','resource-check',disabled)}${back}</div>`;
  }
  return wrap(`<div class="resource-workshop">${html}</div>`,{wide:['resource-plan','resource-source','resource-job','resource-revision','resource-revision-review'].includes(m.kind)});
 }
 async showJob(id,expected=this.g.modal,check=false){const data=await this.request('jobs/'+id+(check?'/check':''),check?{}:undefined);if(this.g.modal!==expected)return;this.g.openModal({kind:'resource-job',job:data.job});this.poll(id)}
 poll(id,delay=4000){
  clearTimeout(this.timer);const m=this.g.modal;
  if(m?.kind!=='resource-job'||m.job.id!==id||!['starting','running'].includes(m.job.status))return;
  this.timer=setTimeout(async()=>{
   if(this.g.modal!==m)return;
   try{const data=await this.request('jobs/'+id+'/check',{});if(this.g.modal===m){m.job=data.job;this.g.renderModal();this.poll(id)}}
   catch(e){if(this.g.modal===m){m.feedback=e.message+' Checking this saved request again shortly.';this.g.renderModal();this.poll(id,15000)}}
  },delay);
 }
 async run(id){if(this.running.has(id))return;this.running.add(id);const m=this.g.modal;if(m?.job?.id===id){m.job.status='starting';this.g.renderModal();this.poll(id)}try{const data=await this.request('jobs/'+id+'/run',{});if(this.g.modal?.job?.id===id){this.g.modal.job=data.job;this.g.renderModal();this.poll(id)}}catch(e){if(this.g.modal?.job?.id===id){this.g.modal.feedback=e.message+' Reopen or refresh this request to check its saved status.';this.g.renderModal()}}finally{this.running.delete(id)}}
 async act(action,el){
  if(!action.startsWith('resource-'))return false;const m=this.g.modal;
  if(action==='resource-open'||action==='resource-refresh'){await this.open();return true}
  if(m?.busy)return true;
  if(action==='resource-revise'&&m?.job?.draft){this.g.openModal({kind:'resource-revision',job:m.job,edited:structuredClone(m.job.draft),requestKey:crypto.randomUUID()});return true}
  if(action==='resource-revision-cancel'){this.g.openModal({kind:'resource-job',job:m.job});return true}
  if(action==='resource-revision-edit'){this.g.openModal({...m,kind:'resource-revision'});return true}
  if(action==='resource-revision-review'){try{if(Object.keys(m.fieldErrors||{}).length)throw Error(Object.values(m.fieldErrors)[0]);const edited=validatePlayableContent(m.edited);this.g.openModal({...m,edited,kind:'resource-revision-review',feedback:''})}catch(e){m.feedback=e.message;this.g.renderModal()}return true}
  if(action==='resource-add'){this.g.openModal({kind:'resource-add'});return true}
  if(action==='resource-plan'){if(!this.form.goal)this.form.goal=learningJournal.profile.goal;if(this.form.level==='New to this topic'&&learningJournal.profile.context)this.form.level=learningJournal.profile.context;const allowed=GAME_TEMPLATES.filter(t=>!this.options.templates||this.options.templates.includes(t.id));if(!allowed.some(t=>t.id===this.template)){this.template=allowed[0]?.id;this.requestKey=null;this.fingerprint=null}this.g.openModal({kind:'resource-plan'});return true}
  if(action==='resource-source'){const r=this.resources.find(r=>r.id===el.dataset.id);if(r)this.g.openModal({kind:'resource-source',resource:r});return true}
  if(action==='resource-download'){this.expansion.download(m.job.draft,m.job.draft.id+'.json');return true}
  if(action==='resource-use'&&m?.job?.status==='published'){try{const draft=validatePlayableContent(m.job.draft);if(draft.template!=='underlight-v1'){if(this.options.onActivate)await this.options.onActivate(draft);else location.assign('/modes.html?job='+encodeURIComponent(m.job.id));return true}if(draft.topicId!==this.g.pack.id)throw Error('Switch to the story used for this request first.');this.g.openModal({kind:'content-review',draft})}catch(e){m.feedback=e.message;this.g.renderModal()}return true}
  m.busy=true;m.feedback='';
  // Capture inputs before rendering the pending state.
  if(action==='resource-upload'){this.form.title=document.querySelector('#resource-title').value;this.form.text=document.querySelector('#resource-text').value}
  if(action==='resource-generate'){this.form.goal=document.querySelector('#resource-goal').value;this.form.level=document.querySelector('#resource-level').value}
  this.g.renderModal();
  try{
   if(action==='resource-revision-save'){const data=await this.request('jobs/'+m.job.id+'/revise',{draftHash:m.job.draftHash,draft:m.edited,requestKey:m.requestKey});await this.refresh();if(this.g.modal===m)this.g.openModal({kind:'resource-job',job:data.job})}
   if(action==='resource-upload'){const data=await this.request('resources',{title:this.form.title,text:this.form.text,filename:this.form.filename});await this.refresh();if(this.g.modal===m)this.g.openModal({kind:'resource-source',resource:data.resource})}
   if(action==='resource-review'){await this.request('resources/'+m.resource.id+'/review',{confirmed:m.confirmed===true,checksum:m.resource.checksum});if(this.g.modal===m)await this.open()}
   if(action==='resource-job')await this.showJob(el.dataset.id);
   if(action==='resource-check')await this.showJob(m.job.id,m,true);
   if(action==='resource-run')await this.run(m.job.id);
   if(action==='resource-generate'){
    const data={template:this.template,topicId:this.g.pack.id,resourceIds:[...this.selected],goal:this.form.goal,level:this.form.level};const fingerprint=JSON.stringify(data);if(this.fingerprint!==fingerprint||!this.requestKey){this.requestKey=crypto.randomUUID();this.fingerprint=fingerprint}
    const result=await this.request('jobs',{...data,requestKey:this.requestKey});this.requestKey=null;this.fingerprint=null;if(this.g.modal===m){this.g.openModal({kind:'resource-job',job:result.job});if(result.job.status==='queued')void this.run(result.job.id);else this.poll(result.job.id)}
   }
   if(action==='resource-publish'){const result=await this.request('jobs/'+m.job.id+'/publish',{confirmed:m.confirmed===true,draftHash:m.job.draftHash});m.job=result.job;await this.refresh()}
  }catch(e){m.feedback=e.message}finally{m.busy=false;if(this.g.modal===m)this.g.renderModal()}return true;
 }
 async change(event){const el=event.target,m=this.g.modal;
  if(el.dataset.revisionPath&&m?.kind==='resource-revision'){m.rawValues={...m.rawValues,[el.dataset.revisionPath]:el.value};try{editRevisionField(m.edited,el.dataset.revisionPath,el.value);if(m.fieldErrors)delete m.fieldErrors[el.dataset.revisionPath];m.requestKey=crypto.randomUUID();m.feedback=''}catch(e){m.fieldErrors={...m.fieldErrors,[el.dataset.revisionPath]:e.message};m.feedback=e.message}el.setAttribute?.('aria-invalid',m.fieldErrors?.[el.dataset.revisionPath]?'true':'false');const error=el.closest?.('.revision-field')?.querySelector('.revision-error');if(error)error.textContent=m.fieldErrors?.[el.dataset.revisionPath]||'';return true}
  if(el.id==='resource-template'){this.template=el.value;this.requestKey=null;this.fingerprint=null;return true}
  if(el.id==='resource-file'&&el.files[0]){try{const file=el.files[0];if(file.size>65536||! /\.(txt|md|markdown)$/i.test(file.name))throw Error('Choose a UTF-8 text or Markdown file, up to 64 KB.');const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(text.length>60000)throw Error('Use at most 60,000 characters in one resource.');this.form.text=text;this.form.filename=file.name;this.form.title=file.name.replace(/\.(txt|md|markdown)$/i,'');m.feedback='File read. Check the text below before saving.'}catch(e){m.feedback=e.message}this.g.renderModal();return true}
  if(el.id==='resource-confirm'||el.id==='draft-confirm'){m.confirmed=el.checked;this.g.renderModal();return true}
  if(el.dataset.resource){el.checked?this.selected.add(el.dataset.resource):this.selected.delete(el.dataset.resource);return true}
  const field={'resource-title':'title','resource-text':'text','resource-goal':'goal','resource-level':'level'}[el.id];if(field){this.form[field]=el.value;return true}return false;
 }
}
