// Authored simulation rules live in town-engine.js. Topic packs supply prose only.
export const TOWN_ENDING='Your town’s ledger records your choices. Compare the actual results below with the targets, then explain one trade-off using your recorded figures and source notes. These fictional outcomes do not measure mastery.';
export const TOWN_BUILDINGS=['home','workshop','market','warehouse','school','clinic','garden','water'];
const str=maxLength=>({type:'string',minLength:1,maxLength});
const id={...str(80),pattern:'^[a-z][a-z0-9-]*$'};
const obj=properties=>({type:'object',properties,required:Object.keys(properties),additionalProperties:false});
const arr=(items,n,maxItems=n)=>({type:'array',items,minItems:n,maxItems});
const refs=arr(id,1,12);
export const TOWN_SCHEMA=obj({schemaVersion:{type:'integer',enum:[1]},template:{type:'string',enum:['town-v1']},id,topicId:id,revision:{type:'integer',minimum:1,maximum:100000},title:str(100),subtitle:str(100),hook:str(800),focus:{type:'string',enum:['enterprise','stewardship']},buildings:arr(obj({id:{type:'string',enum:TOWN_BUILDINGS},name:str(35),purpose:str(300),sourceRefs:refs}),8),events:arr(obj({title:str(80),prompt:str(400),choices:arr(obj({label:str(70),explanation:str(500),sourceRefs:refs}),2)}),4),debrief:obj({question:str(240),explanation:str(500),sourceRefs:refs})});
export const TOWN_PROMPT=`Create The Living Town, a fixed twelve-month educational city/business simulation. Return town-v1. Select focus enterprise or stewardship. The engine, map, costs, goals, effects and numbers are AUTHORED FICTIONAL RULES and cannot be changed by topic text. The engine supplies the ending and goal summary: do not return ending prose, win thresholds, or goal numbers in any narrative field. Enterprise targets are180funds/12residents/4services/50nature; stewardship targets are80funds/12residents/8services/80nature. These values are context only, not narrative content. All labels/narrative must honestly fit those rules. Exactly 8 building entries, one each home/workshop/market/warehouse/school/clinic/garden/water: keep their physical function clear in the name. Homes house 4 people, workshops make goods with upkeep plus a cost of1 per good produced, markets sell goods subject to demand, warehouses increase storage, schools/clinics provide nearby services, gardens/water improve the nature index. Cite evidence for educational purpose; do not invent factual claims about efficiency. Exactly FOUR events in this order, each with TWO choices IN ORDER: (1) month2 market: spend12 on promotion for4 extra demand in the next month OR keep cash with no effect; (2) month5 upkeep: spend8 to gain5 nature OR defer and lose5 nature; (3) month8 rainfall: spend10 to gain6 nature OR defer repairs at no cost and lose6 nature; (4) month11 community: spend12 on shared training to add4 permanent service points OR keep cash with no effect. These effects are fictional abstractions, not real predictions. Show both trade-offs, no correct/incorrect quiz answers. Use each event to connect a principle from supplied sources to the decision; explain the conceptual relationship, not an unsupported quantitative factual claim. All building purposes, event choice explanations and debrief need exact sourceRefs (1–12). If material cannot support this management format, refuse instead of inventing a connection. Do not rename buildings to things unlike their physical function. No URLs, images, code or formulas in output. Use concise readable original prose and a debrief asking the learner to explain a trade-off using their ledger and evidence. Do not claim mastery. Keep source text out of the response; the server attaches it.`;
export function validateTownContent(raw){
 const need=(v,m)=>{if(!v)throw Error(m)};
 const safe=v=>typeof v==='string'&&/^[a-z][a-z0-9-]{0,79}$/.test(v);
 const text=(v,n,label,trim=true)=>{need(typeof v==='string'&&v.trim().length>0&&v.length<=n,`Invalid ${label}.`);return trim?v.trim():v};
 need(raw&&raw.schemaVersion===1&&raw.template==='town-v1'&&safe(raw.id)&&safe(raw.topicId)&&Number.isInteger(raw.revision)&&raw.revision>=1&&raw.revision<=100000,'Invalid town identity.');
 need(['enterprise','stewardship'].includes(raw.focus),'Unknown town goal.');
 need(Array.isArray(raw.sources)&&raw.sources.length>0&&raw.sources.length<=12,'A town needs reviewed sources.');
 const sources=raw.sources.map(s=>{need(s&&safe(s.id),'Invalid source identity.');return {id:s.id,title:text(s.title,160,'source title',false),locator:text(s.locator,240,'source locator',false),excerpt:text(s.excerpt,3000,'source excerpt',false)}});
 const ids=new Set(sources.map(s=>s.id));need(ids.size===sources.length,'Duplicate source identity.');
 const sourceRefs=v=>{need(Array.isArray(v)&&v.length>=1&&v.length<=12&&v.every(x=>ids.has(x)),'Every town learning note needs valid sources.');return [...new Set(v)]};
 need(Array.isArray(raw.buildings)&&raw.buildings.length===8&&new Set(raw.buildings.map(b=>b?.id)).size===8,'Provide exactly eight distinct buildings.');
 const buildings=raw.buildings.map(b=>{need(b&&TOWN_BUILDINGS.includes(b.id),'Unknown town building.');return {id:b.id,name:text(b.name,35,'building name'),purpose:text(b.purpose,300,'building purpose'),sourceRefs:sourceRefs(b.sourceRefs)}});
 need(Array.isArray(raw.events)&&raw.events.length===4,'Provide exactly four town events.');
 const events=raw.events.map(e=>{need(e&&Array.isArray(e.choices)&&e.choices.length===2,'Each town event needs two decisions.');need(e.choices[0]?.label?.trim().toLowerCase()!==e.choices[1]?.label?.trim().toLowerCase(),'Town choices must be distinct.');return {title:text(e.title,80,'event title'),prompt:text(e.prompt,400,'event prompt'),choices:e.choices.map(c=>({label:text(c.label,70,'decision label'),explanation:text(c.explanation,500,'decision explanation'),sourceRefs:sourceRefs(c.sourceRefs)}))}});
 need(raw.debrief&&typeof raw.debrief==='object','Provide a debrief.');
 const clean={schemaVersion:1,template:'town-v1',id:raw.id,topicId:raw.topicId,revision:raw.revision,title:text(raw.title,100,'title'),subtitle:text(raw.subtitle,100,'subtitle'),hook:text(raw.hook,800,'hook'),ending:TOWN_ENDING,focus:raw.focus,buildings,events,debrief:{question:text(raw.debrief.question,240,'debrief question'),explanation:text(raw.debrief.explanation,500,'debrief explanation'),sourceRefs:sourceRefs(raw.debrief.sourceRefs)},sources};
 need(new TextEncoder().encode(JSON.stringify(clean)).length<=70000,'Town packs must be under 70 KB.');return clean;
}
