// The existing commissioned Suno cues; playback always begins with a user gesture.
export class GameAudio {
 constructor(kind,onChange=()=>{}){this.destroyed=false;this.enabled=false;this.track=kind==='sports'?'battle':kind==='novel'?'discovery':'journey';this.onChange=onChange;this.visibility=()=>{if(document.hidden)this.audio?.pause();else if(this.enabled)this.audio?.play().catch(()=>{});};document.addEventListener('visibilitychange',this.visibility);}
 async toggle(){if(this.destroyed)return;this.enabled=!this.enabled;if(!this.enabled){this.audio?.pause();this.onChange();return;}try{this.audio??=new Audio('/audio/'+this.track+'.mp3');this.audio.loop=true;this.audio.volume=.18;await this.audio.play();if(this.destroyed||!this.enabled){this.audio?.pause();return;}this.ctx??=new (window.AudioContext||window.webkitAudioContext)();await this.ctx.resume();this.error='';}catch{this.enabled=false;this.error='Sound is unavailable. The game can still be played.';}this.onChange();}
 effect(kind='choice'){if(!this.enabled||!this.ctx||document.hidden)return;const t=this.ctx.currentTime,notes=kind==='success'?[440,554,660]:kind==='craft'?[262,392,523]:kind==='wrong'?[220,196]:[330];notes.forEach((n,i)=>{const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=n;g.gain.setValueAtTime(.0001,t+i*.09);g.gain.exponentialRampToValueAtTime(.045,t+i*.09+.02);g.gain.exponentialRampToValueAtTime(.0001,t+i*.09+.22);o.connect(g);g.connect(this.ctx.destination);o.start(t+i*.09);o.stop(t+i*.09+.24);o.onended=()=>{o.disconnect();g.disconnect();};});}
 destroy(){this.destroyed=true;this.enabled=false;document.removeEventListener('visibilitychange',this.visibility);this.audio?.pause();this.audio=null;this.ctx?.close().catch(()=>{});}
}
