import {SIZE,MONTHS,BUILDINGS,GOALS,EVENTS,tileXY,isRiver,neighbors,newTown,townStats,pendingEvent,townOutcome,actTown,loadTown,saveTown,townTransactions,encodeTown} from './town-engine.js';
import {TOWN_PACKS,TOWN_SOURCE_URLS} from './town-packs.js';
import './town-style.css';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const signed=n=>(n>=0?'+':'')+n;
const names={funds:'Treasury',people:'Residents',care:'Services',nature:'Nature'};
export function mountTown(root,{pack,assets,onExit,onLibrary,onProgress=()=>{},storage=localStorage}){
 const loaded=loadTown(storage,pack);let state=loaded.state,notice=loaded.notice,tool='inspect',selected=18,modal=null,previousFocus=null,decisionNote=null,destroyed=false;
 const art=assets.town?.buildings||{};
 const name=k=>pack.buildings.find(b=>b.id===k)?.name||BUILDINGS[k]?.name||(k==='hall'?'Town hall':'Empty land');
 const btn=(label,act,extra='',cls='')=>`<button type="button" data-town="${act}" ${extra} class="${cls}">${label}</button>`;
 const tileLabel=i=>{const{x,y}=tileXY(i),kind=state.board[i];return `Tile ${x+1}, ${y+1}: ${kind?name(kind):isRiver(i)?'river':'empty land'}`};
 const anchor=i=>{const{x,y}=tileXY(i);return {x:410+(x-y)*44,y:128+(x+y)*22}};
 const sprite=(kind,x,y,size=116)=>{const item=art[kind];return item?`<image href="${esc(item.url)}" x="${x-size*item.anchor[0]}" y="${y-size*item.anchor[1]}" width="${size}" height="${size}" pointer-events="none"/>`:''};
 const sourceHTML=ids=>ids.map(id=>{const s=pack.sources.find(x=>x.id===id);if(!s)return '';const canonical=TOWN_PACKS.flatMap(p=>p.sources).find(c=>c.id===s.id&&['title','locator','excerpt'].every(k=>c[k]===s[k])),url=canonical?TOWN_SOURCE_URLS[id]:null;return `<blockquote>${esc(s.excerpt)}<footer>${esc(s.title)}<br>${esc(s.locator)}${url?`<br><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Read the original source ↗</a>`:''}</footer></blockquote>`}).join('');
 function mapHTML(stats){
  const ground=Array.from({length:64},(_,i)=>{const p=anchor(i),kind=state.board[i],river=isRiver(i),col=river?'#528d94':(i*13%5===0?'#adb386':i%3?'#b8b98b':'#b0b486');return `<g class="town-tile ${selected===i?'selected':''}" role="button" tabindex="${selected===i?0:-1}" aria-label="${esc(tileLabel(i))}" data-tile="${i}"><path d="M${p.x},${p.y-22} l44,22 -44,22 -44,-22 Z" fill="${col}" fill-opacity="${river?.20:.10}"/>${river?`<path class="river-wave" d="M${p.x-19},${p.y} l20,7 15,-3"/>`:''}${kind==='road'?`<path d="M${p.x},${p.y-16} l34,16 -34,16 -34,-16 Z" fill="${river?'#a48d65':'#d4c7a4'}" stroke="#b4a884"/>`:''}<path class="tile-outline" d="M${p.x},${p.y-22} l44,22 -44,22 -44,-22 Z"/></g>`}).join('');
  const roads=state.board.map((kind,i)=>kind==='road'||kind==='hall'?neighbors(i).filter(n=>n>i&&['road','hall'].includes(state.board[n])).map(n=>{const a=anchor(i),b=anchor(n);return `<path d="M${a.x} ${a.y} L${b.x} ${b.y}" stroke="#d2bf97" stroke-width="16" stroke-linecap="round"/>`}).join(''):'').join('');
  const sorted=state.board.map((kind,i)=>({kind,i})).filter(x=>x.kind&&x.kind!=='road').sort((a,b)=>{const p=tileXY(a.i),q=tileXY(b.i);return p.x+p.y-q.x-q.y||p.x-q.x});
  const buildings=sorted.map(({kind,i})=>{const p=anchor(i);return `<g aria-hidden="true">${sprite(kind,p.x,p.y+18,kind==='hall'?140:120)}${!stats.connected.has(i)?`<circle cx="${p.x}" cy="${p.y+11}" r="7" fill="#d17155" stroke="#412b27"/><path d="M${p.x-3},${p.y+11}h6" stroke="#fff"/>`:''}${kind==='workshop'&&stats.connected.has(i)?`<g class="town-smoke"><circle cx="${p.x+8}" cy="${p.y-65}" r="5"/><circle cx="${p.x+11}" cy="${p.y-76}" r="7"/></g>`:''}</g>`}).join('');
  const trees=Array.from({length:46},(_,i)=>{const side=i%2===0,x=side?58+(i*47%230):565+(i*31%210),y=side?170+(i*17%200):100+(i*19%200),r=11+i%9;return `<g opacity=".83"><ellipse cx="${x+8}" cy="${y+15}" rx="${r}" ry="6" fill="#435d4c" opacity=".25"/><path d="M${x},${y+5}v15" stroke="#685d46" stroke-width="4"/><circle cx="${x}" cy="${y}" r="${r}" fill="${i%2?'#536f57':'#658267'}"/><circle cx="${x-5}" cy="${y-5}" r="${r*.7}" fill="#7e9470"/></g>`}).join('');
  return `<div class="town-map-scroll" style="background-image:url('${esc(assets.town?.backdrop||'')}')" tabindex="0" aria-label="Town map. Scroll horizontally on small screens. Arrow keys move between tiles; Enter selects."><svg class="town-map" viewBox="0 65 820 455" aria-label="Isometric town board"><defs><linearGradient id="town-ground" x2="0" y2="1"><stop stop-color="#afb58d"/><stop offset="1" stop-color="#7d987c"/></linearGradient></defs><rect width="820" height="520" fill="url(#town-ground)"/><path d="M0 410 Q160 360 260 435 T820 430 V520 H0Z" fill="#698b7a" opacity=".35"/><g aria-hidden="true">${assets.town?.backdrop?`<image href="${esc(assets.town.backdrop)}" width="820" height="520" preserveAspectRatio="none"/>`:trees}</g>${ground}<g pointer-events="none" aria-hidden="true">${roads}</g><g class="town-buildings" pointer-events="none">${buildings}</g><text x="28" y="478" class="map-caption">THE RIVERSIDE COMMONS</text><text x="28" y="497" class="map-subcaption">A town in the making</text></svg></div>`;
 }
 function goalsHTML(){const o=townOutcome(pack,state);return `<div class="town-goals">${Object.entries(o.target).map(([k,v])=>`<div><span>${esc(names[k])}</span><strong class="${o.measures[k]>=v?'met':''}">${o.measures[k]} <small>/ ${v}</small></strong></div>`).join('')}</div>`}
 function inspector(stats){const kind=state.board[selected],spec=BUILDINGS[kind],learning=pack.buildings.find(b=>b.id===kind),connected=stats.connected.has(selected);return `<section class="town-inspector"><p class="town-eyebrow">${esc(tileLabel(selected).split(':')[0])}</p><h2>${esc(name(kind))}</h2>${kind&&kind!=='road'?`<img src="${esc(art[kind]?.url||'')}" alt="" class="town-inspect-art">`:''}<p>${kind==='hall'?'The road network starts here. The hall provides 8 civic income and costs 2 each month.':spec?esc(spec.rule):isRiver(selected)?'A living river runs through the town. Keep its course clear.':'Choose a building below, then select this tile to place it.'}</p>${kind?`<p class="town-connection ${connected?'':'offline'}">${connected?'● Connected to the hall':'○ Disconnected · still incurs upkeep'}</p>`:''}${learning?`<p class="town-learning">${esc(learning.purpose)}</p>${btn('Learning notes','evidence',`data-kind="${kind}"`,'text-button')}`:''}</section>`}
 function eventHTML(){const i=pendingEvent(state);if(i<0)return '';const e=pack.events[i];return `<section class="town-council" aria-labelledby="council-title"><p class="town-eyebrow">Council meeting · month ${state.month}</p><h2 id="council-title">${esc(e.title)}</h2><p>${esc(e.prompt)}</p><div class="town-decisions">${e.choices.map((c,j)=>btn(`${esc(c.label)}<small>${EVENTS[i][j].label}</small>`,'decision',`data-choice="${j}" ${state.funds<EVENTS[i][j].cost?'disabled':''}`)).join('')}</div><p class="town-small">Both choices are valid trade-offs. These effects are fictional game rules.</p></section>`}
 function historyHTML(){return state.history.length?`<div class="town-table-scroll"><table><caption>Monthly operating ledger · construction and council payments happen between months</caption><thead><tr><th>Month</th><th>Income</th><th>Costs</th><th>Balance</th><th>Treasury</th><th>Made / sold</th><th>Nature</th></tr></thead><tbody>${state.history.map(h=>`<tr><th>${h.month}</th><td>${h.revenue}</td><td>${h.expenses}</td><td>${signed(h.net)}</td><td>${h.funds}</td><td>${h.production} / ${h.sold}</td><td>${h.nature}</td></tr>`).join('')}</tbody></table></div>`:'<p>Your first monthly record will appear after you advance time.</p>'}
 function endHTML(){return `<section class="town-ending"><p class="town-eyebrow">${state.status==='insolvent'?'The treasury ran out':'The year in review'}</p><h2>${state.status==='complete'?'A town ready for tomorrow':state.status==='insolvent'?'A plan worth revisiting':'Every town tells a story'}</h2><p>${esc(pack.ending)}</p>${goalsHTML()}<h3>${esc(pack.debrief.question)}</h3><p>${esc(pack.debrief.explanation)}</p><div class="town-actions">${btn('Review your ledger','ledger')}${btn('Read the evidence','debrief')}${btn('Start a new town','restart','','primary')}${btn('Back to games','exit')}</div></section>`}
 function render(focusKey){if(destroyed)return;const focused=document.activeElement,oldKey=focusKey||focused?.dataset?.focus||focused?.dataset?.town&&(focused.dataset.town+':'+(focused.dataset.kind||focused.dataset.choice||''))||focused?.dataset?.tile&&('tile:'+focused.dataset.tile),scroll=root.querySelector('.town-map-scroll')?.scrollLeft||0;const stats=townStats(state),e=pendingEvent(state),ended=state.status!=='playing';root.innerHTML=`<div class="living-town"><header class="town-header"><div><p class="town-eyebrow">Lanternbound · The Living Town</p><h1>${esc(pack.title)}</h1><p class="town-subtitle">${esc(pack.subtitle)}</p></div><nav aria-label="Town controls">${btn('Games','exit')}${btn('Rules & sources','rules')}${btn('Create a town','library')}</nav></header><div class="town-stats" aria-label="Current town"><div><span>Treasury</span><strong>${state.funds}</strong></div><div><span>Residents</span><strong>${stats.people}</strong></div><div><span>Goods</span><strong>${state.goods}<small> / ${stats.capacity}</small></strong></div><div><span>Services</span><strong>${stats.care}</strong></div><div><span>Nature</span><strong>${state.nature}<small> / 100</small></strong></div><div><span>Month</span><strong>${state.month}<small> / ${MONTHS}</small></strong></div></div><div class="town-layout"><main class="town-play"><div class="town-map-top"><span>${ended?'Your final town':e>=0?'The council is waiting':tool==='inspect'?'Inspect your town':tool==='remove'?'Remove a building · 50% refund':`Place ${esc(name(tool))} · ${BUILDINGS[tool]?.cost} funds`}</span><span class="town-map-hint">Arrow keys & Enter · or click a tile</span></div>${mapHTML(stats)}<div class="town-tools" aria-label="Build palette">${['inspect','road',...Object.keys(BUILDINGS).filter(k=>k!=='road'),'remove'].map(k=>btn(`${art[k]?`<img src="${esc(art[k].url)}" alt="">`:`<span class="town-tool-symbol">${k==='road'?'═':k==='inspect'?'⌖':'×'}</span>`}<span>${esc(k==='inspect'?'Inspect':k==='remove'?'Remove':name(k))}</span>${BUILDINGS[k]?`<small>${BUILDINGS[k].cost}</small>`:''}`,'tool',`data-kind="${k}" aria-label="${k==='inspect'?'Inspect town':k==='remove'?'Remove building':'Build '+esc(name(k))}" aria-pressed="${tool===k}" ${k!=='inspect'&&(ended||e>=0)?'disabled':''}`,tool===k?'selected':'')).join('')}</div><p class="town-status" role="status">${esc(notice||'Select a building, then a tile. Buildings need an adjacent road connected to the hall.')}</p>${e>=0?eventHTML():decisionNote?`<section class="town-decision-note"><p class="town-eyebrow">Council record</p><h2>${esc(pack.events[decisionNote.event].choices[decisionNote.choice].label)}</h2><p>${esc(pack.events[decisionNote.event].choices[decisionNote.choice].explanation)}</p><p class="town-small">Applied: ${EVENTS[decisionNote.event][decisionNote.choice].label}</p>${btn('Check decision sources','decision-sources')}</section>`:state.month===0?`<section class="town-story"><h2>A town in your hands</h2><p>${esc(pack.hook)}</p><p class="town-small">Time moves only when you advance a month. All costs, demand, service ranges and nature points are fictional rules.</p></section>`:''}${ended?endHTML():''}</main><aside class="town-sidebar" aria-label="Town ledger"><section class="town-forecast"><p class="town-eyebrow">${ended?'Final operating capacity':'Next month · projection'}</p><h2>Every choice leaves a trace.</h2><dl><div><dt>Civic income</dt><dd>+${stats.civicIncome}</dd></div><div><dt>Sales · ${stats.sold} × 4</dt><dd>+${stats.sales}</dd></div><div><dt>Fixed upkeep</dt><dd>−${stats.upkeep}</dd></div><div><dt>Production inputs</dt><dd>−${stats.inputCosts}</dd></div><div class="town-net"><dt>Operating balance</dt><dd>${signed(stats.net)}</dd></div><div><dt>Goods made / sold</dt><dd>${stats.production} / ${stats.sold}</dd></div><div><dt>Demand / sales limit</dt><dd>${stats.demand} / ${state.board.filter((k,i)=>k==='market'&&stats.connected.has(i)).length*6}</dd></div><div><dt>Storage overflow</dt><dd>${stats.waste}</dd></div><div><dt>Nature change</dt><dd>${signed(stats.natureDelta)}</dd></div></dl>${stats.activeWorkshops<stats.workshops?'<p class="town-small">Some workshops lack residents to staff them.</p>':''}${!ended?btn(e>=0?'Resolve council meeting':`Advance to month ${state.month+1}`,'advance',e>=0?'disabled':'','primary'):''}${btn('Monthly ledger','ledger','','text-button')}${!ended?btn('Restart town','restart','','text-button town-restart'):''}</section><section class="town-targets"><p class="town-eyebrow">Your goals · end of month 12</p>${goalsHTML()}</section>${inspector(stats)}</aside></div><footer class="town-footer"><span>Original simulation · all numbers are game assumptions.</span><span>Progress saves on this browser.</span></footer><div class="town-modal-host"></div></div>`;
 root.querySelector('.town-map-scroll').scrollLeft=scroll;if(oldKey){const nodes=[...root.querySelectorAll('[data-town],[data-tile]')];nodes.find(n=>n.dataset.tile!==undefined?'tile:'+n.dataset.tile===oldKey:n.dataset.town+':'+(n.dataset.kind||n.dataset.choice||'')===oldKey)?.focus({preventScroll:true})}if(modal)renderModal();
 }
 function openModal(title,html){previousFocus=document.activeElement;modal={title,html};renderModal();root.querySelector('.town-dialog h2').focus()}
 function renderModal(){const host=root.querySelector('.town-modal-host');if(!modal){host.innerHTML='';return}host.innerHTML=`<div class="town-scrim"><section class="town-dialog" role="dialog" aria-modal="true" aria-labelledby="town-dialog-title"><h2 id="town-dialog-title" tabindex="-1">${esc(modal.title)}</h2>${btn('Close','close','','town-close')}${modal.html}</section></div>`}
 function closeModal(){modal=null;renderModal();previousFocus?.focus()}
 function commit(action){try{state=actTown(pack,state,action);notice=saveTown(storage,pack,state);onProgress({pack,record:encodeTown(pack,state),kind:'classic'});if(pendingEvent(state)>=0||state.status!=='playing')tool='inspect';if(action.type==='decision')decisionNote=state.decisions.at(-1);else if(action.type==='advance')decisionNote=null;if(action.type==='build')notice=notice||`${name(action.kind)} placed. ${townStats(state).connected.has(action.index)?'Connected to the hall.':'Connect an adjacent road to make it work.'}`;render();const heading=state.status!=='playing'?root.querySelector('.town-ending h2'):pendingEvent(state)>=0?root.querySelector('#council-title'):action.type==='decision'?root.querySelector('.town-decision-note h2'):null;if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}if(pendingEvent(state)>=0)root.querySelector('#council-title')?.scrollIntoView({block:'nearest',behavior:'smooth'});if(state.status!=='playing')root.querySelector('.town-ending')?.scrollIntoView({block:'start',behavior:'smooth'})}catch(err){notice=err.message;render()}}
 function chooseTile(i){selected=i;if(tool==='inspect'){render('tile:'+i);return}if(tool==='remove')commit({type:'remove',index:i});else commit({type:'build',kind:tool,index:i})}
 const click=e=>{const tile=e.target.closest('[data-tile]');if(tile){chooseTile(Number(tile.dataset.tile));return}const b=e.target.closest('button[data-town]');if(!b||b.disabled)return;switch(b.dataset.town){case 'exit':onExit();break;case 'library':onLibrary();break;case 'tool':tool=b.dataset.kind;notice=tool==='inspect'?'Select a tile to inspect it.':tool==='remove'?'Select a building or road to remove it. Half its construction cost is returned.':BUILDINGS[tool].rule;render();break;case 'advance':commit({type:'advance'});break;case 'decision':commit({type:'decision',choice:Number(b.dataset.choice)});break;case 'ledger':openModal('The town ledger',historyHTML()+`<h3>Between-month cash movements</h3><p class="town-small">Starting treasury: 200. Construction, removal refunds and council payments are separate from monthly operations.</p><div class="town-table-scroll"><table><thead><tr><th>After month</th><th>Movement</th><th>Change</th><th>Treasury</th></tr></thead><tbody>${townTransactions(pack,state).map(t=>`<tr><td>${t.afterMonth}</td><td>${esc(t.description)}</td><td>${signed(t.change)}</td><td>${t.funds}</td></tr>`).join('')}</tbody></table></div><h3>Council decisions</h3>${state.decisions.map(d=>`<p><b>${esc(pack.events[d.event].title)}</b><br>${esc(pack.events[d.event].choices[d.choice].label)} · ${EVENTS[d.event][d.choice].label}</p>`).join('')}`);break;case 'evidence':{const item=pack.buildings.find(x=>x.id===b.dataset.kind);openModal(name(item.id)+' · learning notes',`<p>${esc(item.purpose)}</p>${sourceHTML(item.sourceRefs)}`);break}case 'decision-sources':{const d=decisionNote;openModal('Evidence behind the decision',sourceHTML(pack.events[d.event].choices[d.choice].sourceRefs));break}case 'debrief':openModal('Explain the trade-off',`<p>${esc(pack.debrief.question)}</p>${sourceHTML(pack.debrief.sourceRefs)}`);break;case 'rules':openModal('How this town works',`<p>Build a connected town and meet all four goals at the end of month 12. There is no timer. Council meetings occur after months 2, 5, 8 and 11. End-of-month treasury below zero ends the run.</p><p>Buildings activate beside a road connected orthogonally to the hall. Disconnected buildings still incur upkeep. The initial hall provides 8 civic income and costs 2 each month. Construction and council payments change cash immediately; monthly income minus upkeep and production inputs is the operating balance. This is a simplified cash model, not accounting profit.</p><p>New goods enter storage before sales; excess stock is lost. Connected homes provide four residents each. Each good produced costs one in inputs, whether sold or stored. Each workshop needs four residents, and each resident supplies one unit of demand. Nature is a bounded 0–100 teaching index. School and clinic ranges use grid steps, not real-world distances.</p>${Object.entries(BUILDINGS).map(([k,v])=>`<p><b>${esc(name(k))} · build ${v.cost}, upkeep ${v.upkeep}</b><br>${esc(v.rule)}</p>`).join('')}<h3>Evidence and assumptions</h3><p>All numerical rules, service effects, income and demand are authored scenario assumptions. Source notes explain selected principles; they do not validate the fictional coefficients. A completed town does not measure mastery.</p>${sourceHTML(pack.sources.map(s=>s.id))}`);break;case 'restart':openModal('Start a new town?',`<p>This replaces the saved run for this story in this browser.</p>${btn('Start fresh','restart-confirm','','primary')}`);break;case 'restart-confirm':modal=null;state=newTown();decisionNote=null;tool='inspect';notice=saveTown(storage,pack,state)||'A new town is ready.';render();const title=root.querySelector('.town-header h1');title.tabIndex=-1;title.focus({preventScroll:true});window.scrollTo({top:0});break;case 'close':closeModal();break}}
 const key=e=>{if(modal){if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const a=[...root.querySelectorAll('.town-dialog button,.town-dialog a')],first=a[0],last=a.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.id==='town-dialog-title')){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}return}const tile=e.target.closest?.('[data-tile]');if(!tile)return;const i=Number(tile.dataset.tile),{x,y}=tileXY(i),move={ArrowLeft:[x-1,y],ArrowRight:[x+1,y],ArrowUp:[x,y-1],ArrowDown:[x,y+1]}[e.key];if(move){e.preventDefault();if(move.every(n=>n>=0&&n<SIZE)){selected=move[1]*SIZE+move[0];render('tile:'+selected)}}else if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseTile(i)}};
 root.addEventListener('click',click);root.addEventListener('keydown',key);render();return {destroy(){destroyed=true;root.removeEventListener('click',click);root.removeEventListener('keydown',key)}};
}
